#!/usr/bin/env bash
# generate-formula.sh — standalone verifier for the radar CLI Homebrew formula.
#
# WHY THIS EXISTS
# ----------------
# This script does NOT fix a bug — see NOTES.md. skyhook-io/radar already
# regenerates and publishes Formula/radar.rb to skyhook-io/homebrew-tap on
# every tagged release, automatically, via GoReleaser (.goreleaser.yaml
# `brews:` stanza, invoked from .github/workflows/release.yml). That pipeline
# is working correctly today.
#
# This script exists purely as evidence: it independently reconstructs the
# formula for a given already-published release by downloading the real
# release assets and hashing them itself (no trust in GoReleaser's own
# checksums.txt), then the caller can diff the result against the live
# tap file. If the two match, the automated pipeline is proven correct
# for that release.
#
# It intentionally mirrors the shape GoReleaser's `brews:` stanza in
# .goreleaser.yaml produces: the same four platform/arch combinations
# (darwin amd64, darwin arm64, linux amd64, linux arm64), the same
# install/test blocks, matching the plain `bin.install` + `bin.install_symlink`
# lines from .goreleaser.yaml's `install:` key.
#
# USAGE
#   ./generate-formula.sh v1.9.2 > radar.rb.generated
#
# Requires: gh (authenticated, for release asset downloads), shasum/sha256sum.

set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "usage: $0 <tag, e.g. v1.9.2>" >&2
  exit 1
fi

TAG="$1"
VERSION="${TAG#v}"
REPO="skyhook-io/radar"

WORKDIR="$(mktemp -d)"
trap 'rm -rf "$WORKDIR"' EXIT

sha256_of() {
  local file="$1"
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$file" | awk '{print $1}'
  else
    shasum -a 256 "$file" | awk '{print $1}'
  fi
}

# platform/arch combos the formula ships, in the same order as the current
# Formula/radar.rb (darwin intel, darwin arm, linux intel, linux arm).
# Plain variables (not an associative array) so this runs under bash 3.2
# (macOS system bash) as well as the bash 5.x on GitHub's ubuntu-latest runners.
download_and_hash() {
  local combo="$1"
  local asset="radar_${TAG}_${combo}.tar.gz"
  local dest="${WORKDIR}/${asset}"
  gh release download "${TAG}" --repo "${REPO}" --pattern "${asset}" --dir "${WORKDIR}" --clobber >&2
  sha256_of "$dest"
}

SHA_DARWIN_AMD64="$(download_and_hash darwin_amd64)"
SHA_DARWIN_ARM64="$(download_and_hash darwin_arm64)"
SHA_LINUX_AMD64="$(download_and_hash linux_amd64)"
SHA_LINUX_ARM64="$(download_and_hash linux_arm64)"

cat <<EOF
# typed: false
# frozen_string_literal: true

# This file was generated by GoReleaser. DO NOT EDIT.
class Radar < Formula
  desc "Modern Kubernetes visibility — topology, traffic, and Helm management"
  homepage "https://github.com/skyhook-io/radar"
  version "${VERSION}"
  license "Apache-2.0"

  on_macos do
    if Hardware::CPU.intel?
      url "https://github.com/skyhook-io/radar/releases/download/${TAG}/radar_${TAG}_darwin_amd64.tar.gz"
      sha256 "${SHA_DARWIN_AMD64}"

      define_method(:install) do
        bin.install "kubectl-radar"
        bin.install_symlink "kubectl-radar" => "radar"
      end
    end
    if Hardware::CPU.arm?
      url "https://github.com/skyhook-io/radar/releases/download/${TAG}/radar_${TAG}_darwin_arm64.tar.gz"
      sha256 "${SHA_DARWIN_ARM64}"

      define_method(:install) do
        bin.install "kubectl-radar"
        bin.install_symlink "kubectl-radar" => "radar"
      end
    end
  end

  on_linux do
    if Hardware::CPU.intel? && Hardware::CPU.is_64_bit?
      url "https://github.com/skyhook-io/radar/releases/download/${TAG}/radar_${TAG}_linux_amd64.tar.gz"
      sha256 "${SHA_LINUX_AMD64}"
      define_method(:install) do
        bin.install "kubectl-radar"
        bin.install_symlink "kubectl-radar" => "radar"
      end
    end
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "https://github.com/skyhook-io/radar/releases/download/${TAG}/radar_${TAG}_linux_arm64.tar.gz"
      sha256 "${SHA_LINUX_ARM64}"
      define_method(:install) do
        bin.install "kubectl-radar"
        bin.install_symlink "kubectl-radar" => "radar"
      end
    end
  end

  test do
    system "#{bin}/kubectl-radar", "--version"
  end
end
EOF
